import React, { useState, useRef, useEffect, KeyboardEvent, ChangeEvent } from "react";
import styles from "../styles/LoginPage.module.css";

type Step = "phone" | "otp" | "success";

const MOCK_OTP = "1234";

export default function LoginPage() {
  const [step, setStep] = useState<Step>("phone");
  const [phone, setPhone] = useState<string>("");
  const [otp, setOtp] = useState<string[]>(["", "", "", ""]);
  const [error, setError] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(false);
  const [resendTimer, setResendTimer] = useState<number>(0);

  const otpRefs = useRef<(HTMLInputElement | null)[]>([]);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (resendTimer > 0) {
      timerRef.current = setInterval(() => {
        setResendTimer((t) => {
          if (t <= 1) {
            if (timerRef.current) clearInterval(timerRef.current);
            return 0;
          }
          return t - 1;
        });
      }, 1000);
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [resendTimer]);

  const isValidPhone = (p: string): boolean => /^[6-9]\d{9}$/.test(p);

  const handleSendOTP = async (): Promise<void> => {
    if (!isValidPhone(phone)) {
      setError("Enter a valid 10-digit Indian mobile number.");
      return;
    }

    setError("");
    setLoading(true);

    await new Promise((r) => setTimeout(r, 1200));

    setLoading(false);
    setStep("otp");
    setResendTimer(30);

    setTimeout(() => otpRefs.current[0]?.focus(), 100);
  };

  const handleOtpChange = (i: number, val: string): void => {
    if (!/^\d?$/.test(val)) return;

    const next = [...otp];
    next[i] = val;
    setOtp(next);
    setError("");

    if (val && i < 3) otpRefs.current[i + 1]?.focus();
  };

  const handleOtpKeyDown = (i: number, e: KeyboardEvent<HTMLInputElement>): void => {
    if (e.key === "Backspace" && !otp[i] && i > 0) {
      otpRefs.current[i - 1]?.focus();
    }
  };

  const handleVerifyOTP = async (): Promise<void> => {
    const entered = otp.join("");

    if (entered.length < 4) {
      setError("Please enter the 4-digit OTP.");
      return;
    }

    if (entered !== MOCK_OTP) {
      setError("Incorrect OTP. Hint: try 1234 😉");
      return;
    }

    setError("");
    setLoading(true);

    await new Promise((r) => setTimeout(r, 1000));

    setLoading(false);
    setStep("success");
  };

  const handleResend = (): void => {
    if (resendTimer > 0) return;

    setOtp(["", "", "", ""]);
    setError("");
    setResendTimer(30);

    setTimeout(() => otpRefs.current[0]?.focus(), 100);
  };

  const handleReset = (): void => {
    setStep("phone");
    setPhone("");
    setOtp(["", "", "", ""]);
    setError("");
    setResendTimer(0);
  };

  return (
    <div className={styles.wrapper}>
      <div className={styles.blob} />

      <div className={styles.container}>
        <div className={styles.card}>
          <div className={styles.accentLine} />

          {/* PHONE STEP */}
          {step === "phone" && (
            <>
              <Logo />
              <h1 className={styles.title}>Welcome back</h1>
              <p className={styles.subtitle}>Sign in with your mobile number</p>

              <input
                type="tel"
                className={styles.phoneInput}
                maxLength={10}
                value={phone}
                placeholder="9876543210"
                onChange={(e: ChangeEvent<HTMLInputElement>) => {
                  setPhone(e.target.value.replace(/\D/g, ""));
                  setError("");
                }}
              />

              {error && <p className={styles.error}>{error}</p>}

              <button className={styles.btn} onClick={handleSendOTP} disabled={loading}>
                {loading ? <Spinner /> : "Send OTP"}
              </button>
            </>
          )}

          {/* OTP STEP */}
          {step === "otp" && (
            <>
              <Logo />
              <h1 className={styles.title}>Verify OTP</h1>

              <div className={styles.otpRow}>
                {otp.map((digit, i) => (
                  <input
                    key={i}
                    ref={(el) => (otpRefs.current[i] = el)}
                    maxLength={1}
                    value={digit}
                    className={styles.otpBox}
                    onChange={(e) => handleOtpChange(i, e.target.value)}
                    onKeyDown={(e) => handleOtpKeyDown(i, e)}
                  />
                ))}
              </div>

              {error && <p className={styles.error}>{error}</p>}

              <button className={styles.btn} onClick={handleVerifyOTP} disabled={loading}>
                {loading ? <Spinner /> : "Verify OTP"}
              </button>
            </>
          )}

          {/* SUCCESS */}
          {step === "success" && (
            <div>
              <h1 className={styles.title}>Success 🎉</h1>
              <button className={styles.btn} onClick={handleReset}>
                Logout
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/* ---------- SMALL COMPONENTS ---------- */

function Logo() {
  return <div style={{ fontWeight: "bold" }}>LOGO</div>;
}

function Spinner() {
  return <span>Loading...</span>;
}
